chartjs.data:
model -> {
	days = now().roundDay()
		.recursion(d -> $d.toSystemCalendar().withDayAdded(-1).toDate().roundDay(), 0, 30)
		.reverse();
	byDay = all(`tl.ai.execution:AgentExecution`)
		.filter(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`) >= $days.firstElement())
		.groupBy(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`).roundDay());
	totals = attr -> $days.map(d -> {
		runs = $byDay[$d];
		ifElse(isEmpty($runs), 0,
			$runs.map(e -> ifElse(isEmpty($e.get($attr)), 0, $e.get($attr))).sum());
	});
	bar = attr -> color -> {
		'label': $attr.label(),
		'data': $totals($attr),
		'backgroundColor': $color
	};
	{
		'type': 'bar',
		'data': {
			'labels': $days.map(d -> dateFormat('dd.MM.').format($d)),
			'datasets': list(
				$bar(`tl.ai.execution:AgentExecution#inputTokens`)('#2968c8'),
				$bar(`tl.ai.execution:AgentExecution#outputTokens`)('#d3a118'),
				$bar(`tl.ai.execution:AgentExecution#thinkingTokens`)('#04a38d'),
				$bar(`tl.ai.execution:AgentExecution#cacheReadTokens`)('#c82968'),
				$bar(`tl.ai.execution:AgentExecution#cacheWriteTokens`)('#6829c8')
			)
		},
		'options': {
			'maintainAspectRatio': false,
			'plugins': { 'legend': { 'position': 'bottom' } },
			'scales': {
				'x': { 'stacked': true },
				'y': { 'stacked': true, 'beginAtZero': true }
			}
		}
	};
}
